-- six classic recipes so the kitchen is not empty on the first day (author empty = "სუფრის რეცეპტები")
insert into public.recipes (author, title, about, category, region, servings, minutes, ingredients, steps) values
(null, 'იმერული ხაჭაპური', 'რბილი მაწვნის ცომი და ბევრი იმერული ყველი. ტაფაზე ცხვება.', 'ცომეული', 'იმერეთი', 4, 90,
 '[{"n":"ფქვილი","q":"500 გ"},{"n":"მაწონი","q":"250 მლ"},{"n":"კვერცხი (ცომში)","q":"1 ცალი"},{"n":"კარაქი","q":"50 გ"},{"n":"სოდა","q":"½ ჩ/კ"},{"n":"მარილი","q":"1 ჩ/კ"},{"n":"შაქარი","q":"1 ჩ/კ"},{"n":"იმერული ყველი","q":"700 გ"},{"n":"კვერცხი (ყველში)","q":"1 ცალი"}]',
 '["მაწონს დაუმატე სოდა, მარილი, შაქარი და კვერცხი, კარგად აურიე.","თანდათან ჩაუმატე ფქვილი და მოზილე რბილი ცომი. ბოლოს შეზილე გალღობილი კარაქის ნახევარი, დააფარე და 30 წუთით დაასვენე.","ყველი დაფშვნე ან დახეხე, შეურიე კვერცხი და დარჩენილი კარაქი.","ცომი ოთხად გაყავი. თითოეული ხელით გაშალე, შუაში ყველის ბურთი ჩადე, კიდეები შეკეცე და ფრთხილად ბრტყლად გაშალე.","გახურებულ ტაფაზე, ზეთის გარეშე, ორივე მხრიდან 4–5 წუთი შეწვი, სანამ ოქროსფერი არ გახდება.","ცხელს წაუსვი კარაქი და მაშინვე მიირთვი."]'),
(null, 'ხინკალი', 'წვნიანი ხორციანი ხინკალი. ჯერ წვენს წრუპავ, კუჭს თეფშზე ტოვებ.', 'ხორციანი', 'მთიულეთი', 4, 120,
 '[{"n":"ფქვილი","q":"700 გ"},{"n":"წყალი (ცომში)","q":"300 მლ"},{"n":"საქონლის ხორცი","q":"500 გ"},{"n":"ღორის ხორცი","q":"300 გ"},{"n":"ხახვი","q":"2 ცალი"},{"n":"ნიორი","q":"2 კბილი"},{"n":"ცივი წყალი (ფარშში)","q":"250 მლ"},{"n":"მარილი","q":"2 ჩ/კ"},{"n":"შავი პილპილი","q":"1 ჩ/კ"},{"n":"ძირა (სურვილისამებრ)","q":"½ ჩ/კ"}]',
 '["ფქვილს დაუმატე ნახევარი ჩაის კოვზი მარილი და წყალი, მოზილე მაგარი ცომი, დააფარე და 30 წუთით დაასვენე.","ხორცი გაატარე ხორცსაკეპ მანქანაში, დაუმატე წვრილად დაჭრილი ხახვი, ნიორი, მარილი, პილპილი და ძირა.","ფარშს ნელ-ნელა დაუმატე ცივი წყალი და ხელით კარგად აურიე, სანამ რბილი და წვნიანი არ გახდება.","ცომი თხლად გააბრტყელე და ჭიქით ამოჭერი 10 სმ-იანი წრეები.","თითოეულ წრეზე დადე სუფრის კოვზი ფარში, კიდეები ნაკეცებად ზემოთ აკეცე და თავზე მაგრად მოუჭირე.","ადუღებულ მოხალისებულ წყალში ჩაყარე, ნელა აურიე და ამოტივტივების შემდეგ კიდევ 10–12 წუთი ადუღე.","მიირთვი ცხლად, შავი პილპილით."]'),
(null, 'ნიგვზიანი ბადრიჯანი', 'შემწვარი ბადრიჯნის რულეტები ნიგვზით და ბროწეულით.', 'ბოსტნეული', '', 4, 60,
 '[{"n":"ბადრიჯანი","q":"3 ცალი"},{"n":"ნიგოზი","q":"200 გ"},{"n":"ნიორი","q":"3 კბილი"},{"n":"ხმელი სუნელი","q":"1 ჩ/კ"},{"n":"უცხო სუნელი","q":"½ ჩ/კ"},{"n":"ღვინის ძმარი","q":"1 ს/კ"},{"n":"ქინძი","q":"½ კონა"},{"n":"ბროწეულის მარცვალი","q":"2 ს/კ"},{"n":"მზესუმზირის ზეთი","q":"100 მლ"},{"n":"მარილი","q":"1 ჩ/კ"}]',
 '["ბადრიჯანი სიგრძეზე 5–7 მმ სისქის ზოლებად დაჭერი, დაამარილე, 20 წუთის შემდეგ კი გაწურე.","ზეთში ორივე მხრიდან შეწვი ოქროსფრამდე და ხელსახოცზე დააწყვე.","ნიგოზი ნივრთან ერთად დაფქვი, დაუმატე სუნელები, ძმარი, დაჭრილი ქინძი, მარილი და 3–4 კოვზი წყალი, რომ რბილი მასა გამოვიდეს.","თითოეულ ზოლზე წაუსვი ნიგვზის მასა და დაახვიე.","თავზე ბროწეული მოაყარე და მაცივარში ერთი საათით გააჩერე."]'),
(null, 'აჯაფსანდალი', 'ზაფხულის ბოსტნეულის ჩაშუშული. კარგია თბილიც და ცივიც.', 'ბოსტნეული', '', 4, 60,
 '[{"n":"ბადრიჯანი","q":"2 ცალი"},{"n":"ბულგარული წიწაკა","q":"2 ცალი"},{"n":"პომიდორი","q":"4 ცალი"},{"n":"კარტოფილი","q":"2 ცალი"},{"n":"ხახვი","q":"2 ცალი"},{"n":"ნიორი","q":"4 კბილი"},{"n":"ცხარე წიწაკა","q":"½ ცალი"},{"n":"ქინძი და რეჰანი","q":"1 კონა"},{"n":"მზესუმზირის ზეთი","q":"80 მლ"},{"n":"ხმელი სუნელი","q":"½ ჩ/კ"},{"n":"მარილი","q":"1 ჩ/კ"}]',
 '["ბოსტნეული კუბიკებად დაჭერი. ბადრიჯანი დაამარილე და 15 წუთის შემდეგ გაწურე.","ხახვი ზეთზე მოშუშე, დაამატე კარტოფილი და 10 წუთი შეწვი.","დაუმატე ბადრიჯანი და წიწაკა და ხუფის ქვეშ 10 წუთი ჩაშუშე.","ჩაყარე პომიდორი, მარილი, სუნელი და ცხარე წიწაკა, კიდევ 15 წუთი ჩაშუშე.","გადმოღებამდე დაამატე დანაყილი ნიორი და დაჭრილი მწვანილი."]'),
(null, 'ლობიო ქოთანში', 'წითელი ლობიო ნელ ცეცხლზე, მჭადთან და მწნილთან ერთად.', 'ბოსტნეული', 'რაჭა', 6, 150,
 '[{"n":"წითელი ლობიო","q":"500 გ"},{"n":"ხახვი","q":"2 ცალი"},{"n":"ნიორი","q":"3 კბილი"},{"n":"ქინძი","q":"1 კონა"},{"n":"ხმელი სუნელი","q":"1 ჩ/კ"},{"n":"უცხო სუნელი","q":"½ ჩ/კ"},{"n":"ცხარე წიწაკა","q":"½ ცალი"},{"n":"მზესუმზირის ზეთი","q":"3 ს/კ"},{"n":"მარილი","q":"1½ ჩ/კ"}]',
 '["ლობიო ღამით წყალში დაალბე, დილით წყალი გადაღვარე.","ქოთანში ან ქვაბში ჩაყარე, ცივი წყალი დაასხი ისე, რომ სამი თითით ფარავდეს, და ნელ ცეცხლზე 1,5–2 საათი მოხარშე.","ხახვი ზეთზე მოშუშე.","ლობიოს ნაწილი ხის კოვზით დაჭყლიტე, დაუმატე ხახვი, სუნელები, მარილი, ცხარე წიწაკა, დანაყილი ნიორი და ქინძი.","კიდევ 10 წუთი ადუღე და მიირთვი."]'),
(null, 'ჩაქაფული', 'გაზაფხულის კერძი: ხორცი ტყემლით, ტარხუნით და თეთრი ღვინით.', 'ხორციანი', 'კახეთი', 4, 90,
 '[{"n":"ბატკნის ან ხბოს ხორცი","q":"1 კგ"},{"n":"მწვანე ტყემალი","q":"200 გ"},{"n":"თეთრი ღვინო","q":"250 მლ"},{"n":"მწვანე ხახვი","q":"2 კონა"},{"n":"ტარხუნა","q":"2 კონა"},{"n":"ქინძი","q":"1 კონა"},{"n":"კამა","q":"½ კონა"},{"n":"ნიორი","q":"4 კბილი"},{"n":"მწვანე ცხარე წიწაკა","q":"1 ცალი"},{"n":"კარაქი","q":"30 გ"},{"n":"მარილი","q":"1½ ჩ/კ"}]',
 '["ხორცი საშუალო ნაჭრებად დაჭერი, ჩადე ქვაბში, დაასხი ღვინო და ცოტა წყალი და ნელ ცეცხლზე 30 წუთი ჩაშუშე.","დაუმატე დაჭრილი მწვანე ხახვი და კარაქი და კიდევ 15 წუთი ჩაშუშე.","ჩაყარე ტყემალი, დაჭრილი ტარხუნა, ქინძი, კამა, ცხარე წიწაკა და მარილი. ხუფის ქვეშ 20–30 წუთი ჩაშუშე, სანამ ხორცი არ დარბილდება.","ბოლოს დაუმატე დანაყილი ნიორი, აურიე და 5 წუთით დაასვენე."]');
